/* @lc app=leetcode id=2055 lang=kotlin */ class Solution { fun platesBetweenCandles(s: String, queries: Array<IntArray>): IntArray = s.runningFold(0) { c, ch -> c + if (ch == '*') 1 else 0 }.let { pl -> s.indices.runningFold(-1) { l, i -> if (s[i] == '|') i else l }.drop(1).let { left -> (s.length - 1 downTo 0).runningFold(Int.MAX_VALUE) { r, i -> if (s[i] == '|') i else r }.drop(1).reversed().let { right -> queries.map { (l, r) -> right[l].let { a -> left[r].let { b -> if (a < b) pl[b] - pl[a] else 0 } } }.toIntArray() } } } }